// Ethereum Keccak-256 (pre-NIST, suffix 0x01, rate 136)
pub fn keccak256(data: &[u8]) -> [u8; 32] {
    const RC: [u64; 24] = [
        0x0000000000000001, 0x0000000000008082, 0x800000000000808A,
        0x8000000080008000, 0x000000000000808B, 0x0000000080000001,
        0x8000000080008081, 0x8000000000008009, 0x000000000000008A,
        0x0000000000000088, 0x0000000080008009, 0x000000008000000A,
        0x000000008000808B, 0x800000000000008B, 0x8000000000008089,
        0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
        0x000000000000800A, 0x800000008000000A, 0x8000000080008081,
        0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
    ];
    const RHO: [[u32; 5]; 5] = [
        [0, 36, 3, 41, 18],
        [1, 44, 10, 45, 2],
        [62, 6, 43, 15, 61],
        [28, 55, 25, 21, 56],
        [27, 20, 39, 8, 14],
    ];
    #[inline]
    fn rot(x: u64, n: u32) -> u64 {
        let n = n % 64;
        if n == 0 { x } else { x.rotate_left(n) }
    }
    fn keccak_f(state: &mut [[u64; 5]; 5]) {
        for &rc in RC.iter() {
            // Theta
            let mut c = [0u64; 5];
            for x in 0..5 {
                c[x] = state[x][0] ^ state[x][1] ^ state[x][2] ^ state[x][3] ^ state[x][4];
            }
            let mut d = [0u64; 5];
            for x in 0..5 {
                d[x] = c[(x + 4) % 5] ^ rot(c[(x + 1) % 5], 1);
            }
            for x in 0..5 {
                for y in 0..5 {
                    state[x][y] ^= d[x];
                }
            }
            // Rho Pi
            let mut b = [[0u64; 5]; 5];
            for x in 0..5 {
                for y in 0..5 {
                    b[y][(2 * x + 3 * y) % 5] = rot(state[x][y], RHO[x][y]);
                }
            }
            // Chi
            for x in 0..5 {
                for y in 0..5 {
                    state[x][y] = b[x][y] ^ ((!b[(x + 1) % 5][y]) & b[(x + 2) % 5][y]);
                }
            }
            // Iota
            state[0][0] ^= rc;
        }
    }

    let rate = 136usize;
    // padded message
    let mut padded: Vec<u8> = Vec::with_capacity(((data.len() + 1 + rate - 1) / rate) * rate);
    padded.extend_from_slice(data);
    padded.push(0x01);
    while padded.len() % rate != 0 {
        padded.push(0x00);
    }
    let last = padded.len() - 1;
    padded[last] |= 0x80;

    let mut state = [[0u64; 5]; 5];
    for chunk in padded.chunks(rate) {
        // xor chunk into state (little-endian lanes)
        for (i, &byte) in chunk.iter().enumerate() {
            let lane = i / 8;
            let shift = (i % 8) * 8;
            let x = lane % 5;
            let y = lane / 5;
            state[x][y] ^= (byte as u64) << shift;
        }
        keccak_f(&mut state);
    }
    let mut out = [0u8; 32];
    for i in 0..32 {
        let lane = i / 8;
        let shift = (i % 8) * 8;
        let x = lane % 5;
        let y = lane / 5;
        out[i] = ((state[x][y] >> shift) & 0xFF) as u8;
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_vectors() {
        assert_eq!(hex::encode(keccak256(b"")), "c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470");
        assert_eq!(hex::encode(keccak256(b"Transfer(address,address,uint256)")), "ddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef");
    }
}
