{"command":"cat > src/param_type.rs <<'RS'
use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParamType {
    Address,
    Bytes,
    Int(usize),
    Uint(usize),
    Bool,
    String,
    Array(Box<ParamType>),
    FixedArray(Box<ParamType>, usize),
    FixedBytes(usize),
    Tuple(Vec<ParamType>),
}

#[derive(Debug, Clone)]
pub enum TypeParseError {
    Integer(String), // message like "invalid digit found in string" or "number too large..."
    InvalidName(String), // original string
}

impl fmt::Display for TypeParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TypeParseError::Integer(msg) => write!(f, "Integer parsing error: {}", msg),
            TypeParseError::InvalidName(name) => write!(f, "Invalid name: {}", name),
        }
    }
}

impl ParamType {
    pub fn is_dynamic(&self) -> bool {
        match self {
            ParamType::Bytes | ParamType::String | ParamType::Array(_) => true,
            ParamType::FixedArray(t, _) => t.is_dynamic(),
            ParamType::Tuple(ts) => ts.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }
}

impl fmt::Display for ParamType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParamType::Address => write!(f, "address"),
            ParamType::Bytes => write!(f, "bytes"),
            ParamType::Int(n) => write!(f, "int{}", n),
            ParamType::Uint(n) => write!(f, "uint{}", n),
            ParamType::Bool => write!(f, "bool"),
            ParamType::String => write!(f, "string"),
            ParamType::Array(t) => write!(f, "{}[]", t),
            ParamType::FixedArray(t, n) => write!(f, "{}[{}]", t, n),
            ParamType::FixedBytes(n) => write!(f, "bytes{}", n),
            ParamType::Tuple(ts) => {
                write!(f, "(")?;
                for (i, t) in ts.iter().enumerate() {
                    if i > 0 { write!(f, ",")?; }
                    write!(f, "{}", t)?;
                }
                write!(f, ")")
            }
        }
    }
}

fn parse_usize_number(s: &str) -> Result<usize, TypeParseError> {
    // Use Rust's parse to get exact error messages
    match s.parse::<usize>() {
        Ok(v) => Ok(v),
        Err(e) => {
            // e.to_string() gives "invalid digit found in string" or "number too large..."
            Err(TypeParseError::Integer(e.to_string()))
        }
    }
}

fn is_numeric_prefix(s: &str) -> bool {
    s.starts_with("uint") || s.starts_with("int") || s.starts_with("bytes")
}

// Split tuple inner content on commas at depth 0 (tracking () and [])
fn split_tuple_inner(inner: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut depth_paren: i32 = 0;
    let mut depth_bracket: i32 = 0;
    for ch in inner.chars() {
        match ch {
            '(' => { depth_paren += 1; current.push(ch); }
            ')' => { depth_paren -= 1; current.push(ch); }
            '[' => { depth_bracket += 1; current.push(ch); }
            ']' => { depth_bracket -= 1; current.push(ch); }
            ',' if depth_paren == 0 && depth_bracket == 0 => {
                parts.push(current);
                current = String::new();
            }
            _ => { current.push(ch); }
        }
    }
    parts.push(current);
    parts
}

// Split array value string similarly (for value parsing, but also for type? No, types don't need value split)
// For type parsing of arrays, we parse suffixes from end.

pub fn parse_type(s: &str) -> Result<ParamType, TypeParseError> {
    // Exact matches first (including tuple alone)
    if s == "address" { return Ok(ParamType::Address); }
    if s == "bool" { return Ok(ParamType::Bool); }
    if s == "string" { return Ok(ParamType::String); }
    if s == "bytes" { return Ok(ParamType::Bytes); }
    if s == "tuple" { return Ok(ParamType::Tuple(vec![])); }
    if s == "uint" { return Ok(ParamType::Uint(256)); }
    if s == "int" { return Ok(ParamType::Int(256)); }

    // tuple(...) handling: starts with "tuple" and remainder starts with "("
    if s.starts_with("tuple") {
        let rest = &s[5..];
        if rest.starts_with("(") {
            // If rest contains ')', it's InvalidName, else default
            if rest.contains(')') {
                return Err(TypeParseError::InvalidName(s.to_string()));
            } else {
                // e.g., "tuple(" -> default
                return Ok(ParamType::Uint(8));
            }
        }
        // If rest starts with "[" (like tuple[], tuple[2]), handle as array with base tuple
        // Fall through to array handling below (which will parse base "tuple" + suffixes)
        // But need to ensure "tuple " (with space) defaults, not array
        // "tuple " rest is " ", doesn't start with "[" or "(", so fall through to default logic below
        // For "tuple[]", it ends with "]", will be handled as array
        // For "tuple", already handled above
        // For other "tupleX" (like "tupleX", "tuple ", etc.), should default (unless numeric? tuple is not numeric)
        // So if rest is non-empty and doesn't start with "[" and doesn't start with "(", default
        if !rest.is_empty() && !rest.starts_with("[") {
            // e.g., "tuple ", "tupleX", "tuple\t", etc.
            // Check if contains brackets/parens that would trigger Integer/InvalidName?
            // "tuple " has no brackets/parens, default
            // What about "tuple[..."? Already starts with "[", so not here
            // So default, but need to check for Integer/InvalidName cases involving brackets/parens?
            // "tuple " has no brackets, default. Good.
            // What about "tuple(uint"? rest "(uint", starts with "(", no ")", default (handled above, rest.contains(')') false -> default). Already returned above.
            // So here, rest doesn't start with "(" or "[", so default, unless it contains "]" or ")" that would make InvalidName/Integer?
            // Example: "tuple]"? rest "]", doesn't start with "[" or "(", contains "]", ends with "]". Should it be Integer or default or InvalidName?
            // Not tested. Let's apply general rules below: if contains brackets/parens, handle accordingly.
            // For simplicity, fall through to general bracket/paren handling below, which will give appropriate error/default.
            // But to avoid infinite recursion, just fall through.
        } else if rest.starts_with("[") {
            // Array of tuple, parse as array below
            // Fall through
        } else {
            // rest empty? Already handled "tuple" exact above, so rest empty shouldn't happen here (since s=="tuple" returned). But just in case.
            return Ok(ParamType::Tuple(vec![]));
        }
        // If we reach here with rest starting with "[", continue to array parsing
        // If rest is other (like " ", "X"), continue to general handling which will default/Integer
    }

    // Check for parens: contains '(' or ')'
    let has_paren = s.contains('(') || s.contains(')');
    if has_paren {
        // If starts with "(" and ends with ")" -> try tuple parse
        if s.starts_with("(") && s.ends_with(")") {
            // Strip outer parens (first and last char)
            // Need to ensure outer parens are matching? For "(a)b)"? Starts with "(", ends with ")", inner "(a)b"? Splitting would handle, but is it valid tuple?
            // For "(a)b)"? Actually "(a)b)" inner "a)b"? Hmm. But such cases are obscure.
            // For valid tuples like "(bool)", "(bool,string)", "()", "(,)", etc., parse.
            // For "(bool" (starts with "(", doesn't end with ")") -> handled below (default)
            // For now, parse as tuple:
            let inner = &s[1..s.len()-1];
            // Split on commas at depth 0
            let raw_parts = split_tuple_inner(inner);
            // Filter out exactly empty strings (from ,, or leading/trailing commas)
            // Note: " " (space) is not empty, keep it (will default to uint8)
            let mut types = Vec::new();
            for part in raw_parts {
                if part.is_empty() {
                    continue; // ignore empty
                }
                // Recursively parse part (may default to uint8 or error)
