    Uint(usize),
    Bool,
    String,
    Array(Box<ParamType>),
    FixedArray(Box<ParamType>, usize),
    FixedBytes(usize),
    Tuple(Vec<ParamType>),
}

#[derive(Debug, Clone)]
pub enum TypeParseError {
    Integer(String), // message like "invalid digit found in string" or "number too large..."
    InvalidName(String), // original string
}

impl fmt::Display for TypeParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TypeParseError::Integer(msg) => write!(f, "Integer parsing error: {}", msg),
            TypeParseError::InvalidName(name) => write!(f, "Invalid name: {}", name),
        }
    }
}

impl ParamType {
    pub fn is_dynamic(&self) -> bool {
        match self {
            ParamType::Bytes | ParamType::String | ParamType::Array(_) => true,
            ParamType::FixedArray(t, _) => t.is_dynamic(),
            ParamType::Tuple(ts) => ts.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }
}

impl fmt::Display for ParamType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParamType::Address => write!(f, "address"),
            ParamType::Bytes => write!(f, "bytes"),
            ParamType::Int(n) => write!(f, "int{}", n),
            ParamType::Uint(n) => write!(f, "uint{}", n),
            ParamType::Bool => write!(f, "bool"),
            ParamType::String => write!(f, "string"),
            ParamType::Array(t) => write!(f, "{}[]", t),
