use crate::param_type::ParamType;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token {
    Address([u8; 20]),
    FixedBytes(Vec<u8>),
    Bytes(Vec<u8>),
    Int([u8; 32]),
    Uint([u8; 32]),
    Bool(bool),
    String(String),
    Array(Vec<Token>),
    FixedArray(Vec<Token>),
    Tuple(Vec<Token>),
}

impl Token {
    pub fn is_dynamic(&self) -> bool {
        match self {
            Token::Bytes(_) | Token::String(_) | Token::Array(_) => true,
            Token::FixedArray(tokens) => {
                // If empty, consider static? For encoding, FixedArray([]) with 0 elements gives 0 bytes (static)
                // Check if any element dynamic
                tokens.iter().any(|t| t.is_dynamic())
            }
            Token::Tuple(tokens) => tokens.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }

    // Display value part (without type) for decode output
    // For numbers (Uint/Int), display as hex trimmed (lowercase, no 0x, "0" for zero)
    // For Address, display as 40 hex chars (lowercase)
    // For FixedBytes/Bytes, display as hex (lowercase, no 0x, empty for empty)
    // For Bool, "true"/"false"
    // For String, raw string (lossy? Already String)
    // For Array/FixedArray, "[v1,v2,...]" where each vi is display of element (without type)
    // For Tuple, "(v1,v2,...)"
    pub fn display_value(&self) -> String {
        match self {
            Token::Address(a) => hex::encode(a),
            Token::FixedBytes(b) => hex::encode(b),
            Token::Bytes(b) => hex::encode(b),
            Token::Int(bytes) => format_uint_bytes(bytes),
            Token::Uint(bytes) => format_uint_bytes(bytes),
            Token::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Token::String(s) => s.clone(),
            Token::Array(tokens) => {
                let inner: Vec<String> = tokens.iter().map(|t| t.display_value()).collect();
                format!("[{}]", inner.join(","))
            }
            Token::FixedArray(tokens) => {
                let inner: Vec<String> = tokens.iter().map(|t| t.display_value()).collect();
                format!("[{}]", inner.join(","))
            }
            Token::Tuple(tokens) => {
                let inner: Vec<String> = tokens.iter().map(|t| t.display_value()).collect();
                format!("({})", inner.join(","))
            }
        }
    }
}

pub fn format_uint_bytes(bytes: &[u8; 32]) -> String {
    // Trim leading zeros, display as hex lowercase without 0x, "0" for zero
    // Find first non-zero byte
    let mut start = 0;
    while start < 32 && bytes[start] == 0 {
        start += 1;
    }
    if start == 32 {
        return "0".to_string();
