    // Let's implement and test.
    if s.is_empty() {
        // What error for empty? For uint, empty gives InvalidCharacter? Not tested, but likely. For int, similar?
        return Err("InvalidCharacter".to_string());
    }
    let (negative, digits) = if s.starts_with('-') {
        if s.len() == 1 {
            return Err("InvalidCharacter".to_string()); // just "-"?
        }
        (true, &s[1..])
    } else {
        (false, s)
