new2 = """pub fn parse_int_decimal(s: &str) -> Result<[u8; 32], String> {
    // Int lenient parsing uses U256 for absolute value, hence Uint errors for invalid chars/overflow beyond U256.
    // Logic: if starts with '-', strip ALL leading '-' (trim_start_matches), negative=true, digits=remainder (may be empty -> 0).
