use std::fmt;

#[derive(Debug, Clone)]
pub enum AppError {
    // Runtime errors (printed as "Error: ..." to stderr, exit 1)
    HexParsing { msg: String }, // "Hex parsing error: {msg}" + caused by
    Simple(String), // "Error: {msg}" without caused by (e.g., "Invalid data", "Invalid input length", "Invalid name: ...", etc.)
    UintParse(String), // "Uint parse error: {msg}" (InvalidCharacter/InvalidLength)
    IntParse(String), // "int256 parse error: {msg}" (Overflow/Underflow)
    IntegerParse { msg: String }, // "Integer parsing error: {msg}" + caused by
    InvalidFunctionSignature(String), // "invalid function signature `{}`" (lowercase)
    InvalidSignatureHash(String), // "Invalid signature `{}`" with hash (for events)
    MoreThanOne(String), // "More than one function found for name `{}`, try providing the full signature"
    Serialization { msg: String }, // "Serialization error: {msg}" + caused by
    Io(String), // "No such file..." etc. (from std::io::Error display)
}

impl AppError {
    pub fn print_and_exit(&self) -> ! {
        use std::io::Write;
        let stderr = std::io::stderr();
        let mut h = stderr.lock();
        match self {
            AppError::HexParsing { msg } => {
                let _ = writeln!(h, "Error: Hex parsing error: {}", msg);
                let _ = writeln!(h, "");
                let _ = writeln!(h, "Caused by:");
                let _ = writeln!(h, "    {}", msg);
            }
            AppError::IntegerParse { msg } => {
                let _ = writeln!(h, "Error: Integer parsing error: {}", msg);
                let _ = writeln!(h, "");
                let _ = writeln!(h, "Caused by:");
                let _ = writeln!(h, "    {}", msg);
            }
            AppError::Serialization { msg } => {
                let _ = writeln!(h, "Error: Serialization error: {}", msg);
                let _ = writeln!(h, "");
                let _ = writeln!(h, "Caused by:");
                let _ = writeln!(h, "    {}", msg);
            }
            AppError::Simple(msg) => {
                let _ = writeln!(h, "Error: {}", msg);
            }
            AppError::UintParse(msg) => {
                let _ = writeln!(h, "Error: Uint parse error: {}", msg);
            }
            AppError::IntParse(msg) => {
                let _ = writeln!(h, "Error: int256 parse error: {}", msg);
            }
            AppError::InvalidFunctionSignature(sig) => {
                let _ = writeln!(h, "Error: invalid function signature `{}`", sig);
            }
            AppError::InvalidSignatureHash(hash) => {
                let _ = writeln!(h, "Error: Invalid signature `{}`", hash);
            }
            AppError::MoreThanOne(name) => {
                let _ = writeln!(h, "Error: More than one function found for name `{}`, try providing the full signature", name);
            }
            AppError::Io(msg) => {
                let _ = writeln!(h, "Error: {}", msg);
            }
        }
        std::process::exit(1);
    }
}

// Helpers to create errors
pub fn invalid_data() -> AppError { AppError::Simple("Invalid data".to_string()) }
pub fn invalid_input_length() -> AppError { AppError::Simple("Invalid input length".to_string()) }
pub fn invalid_name(name: &str) -> AppError { AppError::Simple(format!("Invalid name: {}", name)) }
pub fn empty_bytes_error() -> AppError {
    AppError::Simple("Invalid name: please ensure the contract and method you're calling exist! failed to decode empty bytes. if you're using jsonrpc this is likely due to jsonrpc returning `0x` in case contract or method don't exist".to_string())
}
