        Err(e) => {
            // e.to_string() gives "Odd number of digits" or "Invalid character 'x' at position N"
            // Note: hex crate's error positions are relative to stripped (since we pass stripped). Good.
            // But need to check: for s="0xzz" (stripped "zz"), error position 0 (relative to stripped). Observed for bytes "0xzz" gave position 0. Good.
            // For s="0x00zz" (stripped "00zz"), error position 2. Observed gave position 2. Good.
            Err(AppError::HexParsing { msg: e.to_string() })
        }
    }
}

