pub fn decode_hex_encode_no_strip(s: &str) -> Result<Vec<u8>, AppError> {
    match hex::decode(s) {
        Ok(b) => Ok(b),
        Err(e) => Err(AppError::HexParsing { msg: e.to_string() }),
    }
