    let stripped = strip_0x(s);
    // Validate hex chars first: check each char is hex digit
    for (i, ch) in stripped.chars().enumerate() {
        if !ch.is_ascii_hexdigit() {
            return Err(AppError::Simple(format!("Invalid character '{}' at position {}", ch, i)));
        }
    }
    // Check length: must be 64 hex chars (32 bytes). Note: stripped length odd but all valid hex (like "123") will have passed above, now length check fails -> Invalid input length. Good.
    if stripped.len() != 64 {
        return Err(crate::errors::invalid_input_length());
    }
    // Now decode (should succeed, since valid hex and even length 64)
    let bytes = hex::decode(stripped).unwrap();
    let mut out = [0u8; 32];
    out.copy_from_slice(&bytes);
    Ok(out)
}
