{"command":"cat > src/value.rs <<'RS'
use crate::param_type::ParamType;
use crate::token::{Token, parse_uint_decimal, parse_int_decimal};
use crate::errors::{AppError, invalid_data};
use crate::hex_utils::{decode_hex_encode_stripped, decode_hex_encode_no_strip};

// Split array/tuple value content on commas at depth 0 (tracking [] and ())
fn split_value_inner(inner: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut depth_paren: i32 = 0;
    let mut depth_bracket: i32 = 0;
    for ch in inner.chars() {
        match ch {
            '(' => { depth_paren += 1; current.push(ch); }
            ')' => { depth_paren -= 1; current.push(ch); }
            '[' => { depth_bracket += 1; current.push(ch); }
            ']' => { depth_bracket -= 1; current.push(ch); }
            ',' if depth_paren == 0 && depth_bracket == 0 => {
                parts.push(current);
                current = String::new();
            }
            _ => { current.push(ch); }
        }
    }
    parts.push(current);
    parts
}

pub fn parse_value(param_type: &ParamType, value: &str, lenient: bool) -> Result<Token, AppError> {
    match param_type {
        ParamType::Bool => {
            if value == "1" || value == "true" {
                Ok(Token::Bool(true))
            } else if value == "0" || value == "false" {
                Ok(Token::Bool(false))
            } else {
                Err(invalid_data())
            }
        }
        ParamType::Uint(_) => {
            if lenient {
                match parse_uint_decimal(value) {
                    Ok(bytes) => Ok(Token::Uint(bytes)),
                    Err(msg) => Err(AppError::UintParse(msg)),
                }
            } else {
                let bytes = decode_hex_encode_no_strip(value)?;
                if bytes.len() != 32 {
                    return Err(invalid_data());
