use crate::token::Token;

fn pad_to_32(data: &[u8]) -> Vec<u8> {
    let mut out = data.to_vec();
    let rem = out.len() % 32;
    if rem != 0 {
        out.extend(vec![0u8; 32 - rem]);
    }
    out
}

fn encode_uint256_value(n: usize) -> [u8; 32] {
    // Encode usize as 32-byte big-endian (for offsets, lengths)
    let mut out = [0u8; 32];
    // n fits in usize (64-bit), put in last 8 bytes
    let bytes = (n as u64).to_be_bytes();
    out[24..32].copy_from_slice(&bytes);
    out
}

