// Else (no '(') -> treat as name: look up functions with exact name match. If none, Invalid name. If multiple, MoreThanOne. Else, return single.
pub fn find_function<'a>(contract: &'a Contract, name_or_sig: &str) -> Result<&'a Function, AppError> {
    if name_or_sig.contains('(') {
        // Signature
        let name = name_or_sig.split('(').next().unwrap_or("");
        // Note: split('(') for "(bar" gives ["", "bar"], next() is "" (empty). Good. For "bar(address)", gives ["bar", "address)"], next() "bar". Good.
        let candidates: Vec<&Function> = contract.functions.iter().filter(|f| f.name == name).collect();
        if candidates.is_empty() {
            return Err(crate::errors::invalid_name(name));
        }
        // Filter by full signature match (exact string, no trimming, case-sensitive)
        for f in candidates {
            if f.signature() == name_or_sig {
                return Ok(f);
            }
        }
        return Err(AppError::InvalidFunctionSignature(name_or_sig.to_string()));
    } else {
        // Name
