        let truncated = format!("0x{}…{}", &hex_hash[0..4], &hex_hash[hex_hash.len()-4..]);
        return Err(AppError::InvalidSignatureHash(truncated));
    } else {
        let candidates: Vec<&Event> = contract.events.iter().filter(|e| e.name == name_or_sig).collect();
        if candidates.is_empty() {
            return Err(crate::errors::invalid_name(name_or_sig));
        }
        if candidates.len() > 1 {
            // Note: error says "function" even for events!
            return Err(AppError::MoreThanOne(name_or_sig.to_string()));
        }
        Ok(candidates[0])
    }
}
