use std::io::Write;

fn print_stdout(s: &str) {
    let stdout = std::io::stdout();
    let mut h = stdout.lock();
    let _ = h.write_all(s.as_bytes());
}

fn print_stderr(s: &str) {
    let stderr = std::io::stderr();
    let mut h = stderr.lock();
    let _ = h.write_all(s.as_bytes());
}

fn exit(code: i32) -> ! {
    std::process::exit(code);
}

// CLI error helpers (clap-like, to stderr, exit 1)
fn cli_error_found_arg(arg: &str, usage: &str) -> ! {
    print_stderr(&format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {}\n\nFor more information try --help\n", arg, usage));
