fn decode_log_run(abi_path: &str, event_sig: &str, topics_strs: &[String], data_str: &str) {
    use crate::abi::{load_contract, find_event};
    use crate::hex_utils::{decode_hex_topic, decode_hex_data};
    use crate::decoder::decode;
    use crate::token::Token;
    let contract = match load_contract(abi_path) {
        Ok(c) => c,
        Err(e) => e.print_and_exit(),
    };
    let event = match find_event(&contract, event_sig) {
        Ok(e) => e,
        Err(e) => e.print_and_exit(),
    };
    // Decode topics
    let mut topics: Vec<[u8; 32]> = Vec::new();
    for s in topics_strs {
        match decode_hex_topic(s) {
            Ok(t) => topics.push(t),
            Err(e) => e.print_and_exit(),
        }
    }
    let data_bytes = match decode_hex_data(data_str) {
        Ok(b) => b,
        Err(e) => e.print_and_exit(),
    };
    // Split inputs
    let indexed_params: Vec<&crate::abi::EventParam> = event.inputs.iter().filter(|p| p.indexed).collect();
    let non_indexed_params: Vec<&crate::abi::EventParam> = event.inputs.iter().filter(|p| !p.indexed).collect();
    // Validate topics count and sig
    if !event.anonymous {
        // Need 1 + indexed.len()
        if topics.len() != 1 + indexed_params.len() {
            crate::errors::invalid_data().print_and_exit();
        }
        // Check sig
        let expected = event.signature_hash();
        if topics[0] != expected {
            crate::errors::invalid_data().print_and_exit();
        }
    } else {
        if topics.len() != indexed_params.len() {
            crate::errors::invalid_data().print_and_exit();
        }
    }
    // Decode indexed
    let mut indexed_tokens: Vec<Token> = Vec::new();
    for (i, param) in indexed_params.iter().enumerate() {
        let topic_idx = if event.anonymous { i } else { 1 + i };
        let topic_bytes = &topics[topic_idx];
        if param.kind.is_dynamic() {
            // Hashed: return FixedBytes of topic hash (32 bytes)
            indexed_tokens.push(Token::FixedBytes(topic_bytes.to_vec()));
        } else {
            // Static: decode from 32-byte topic as single type
            let single_type = std::slice::from_ref(&param.kind);
            // topic_bytes as &[u8] with len 32 (non-empty, so decode won't give long, only Invalid data on failure)
            match decode(single_type, topic_bytes) {
                Ok(mut toks) => {
                    assert_eq!(toks.len(), 1);
                    indexed_tokens.push(toks.remove(0));
                }
                Err(e) => e.print_and_exit(),
            }
        }
    }
    // Decode non-indexed from data
    let non_indexed_types: Vec<crate::param_type::ParamType> = non_indexed_params.iter().map(|p| p.kind.clone()).collect();
    let non_indexed_tokens = match decode(&non_indexed_types, &data_bytes) {
        Ok(t) => t,
        Err(e) => e.print_and_exit(),
    };
    // Recombine in original order for display (name + value)
    if event.inputs.is_empty() {
        print_stdout("\n");
        return;
    }
    // Map indexed and non-indexed tokens back to original order
    // indexed_tokens in order of indexed_params (which is original order filtered), similarly non-indexed.
    // Iterate over original inputs in order, picking next indexed or non-indexed token accordingly.
    let mut out = String::new();
    let mut idx_i = 0;
    let mut non_i = 0;
    for param in &event.inputs {
        if param.indexed {
            let tok = &indexed_tokens[idx_i];
            idx_i += 1;
            out.push_str(&format!("{} {}\n", param.name, tok.display_value()));
        } else {
            let tok = &non_indexed_tokens[non_i];
            non_i += 1;
            out.push_str(&format!("{} {}\n", param.name, tok.display_value()));
        }
    }
    print_stdout(&out);
}
